    <tr style="background:#172033;">
    <td style="padding:10px;border:1px solid #475569;vertical-align:top;">U.S. Constitution</td>
    <td style="padding:10px;border:1px solid #475569;vertical-align:top;">1787 (ratified 1788)</td>
    <td style="padding:10px;border:1px solid #475569;vertical-align:top;">Create the structure of the national government</td>
    </tr>
    <tr>
